CREATE OR REPLACE FUNCTION public.payment_snapshot(u uuid, all_publishers boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p public.publisher_payment_policy; next_date timestamptz; totals jsonb; BEGIN
p:=public.payment_policy_current(); next_date:=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'+make_interval(days=>((p.weekday-extract(dow from now() AT TIME ZONE 'UTC')::integer+7)%7),hours=>p.hour_utc); IF next_date<=now() THEN next_date:=next_date+interval '7 days'; END IF;
IF all_publishers THEN SELECT jsonb_build_object('estimated',coalesce(sum((v->>'estimated')::numeric),0)::text,'verification',coalesce(sum((v->>'verification')::numeric),0)::text,'finalized',coalesce(sum((v->>'finalized')::numeric),0)::text,'available',coalesce(sum((v->>'available')::numeric),0)::text,'paid',coalesce(sum((v->>'paid')::numeric),0)::text,'adjustments',coalesce(sum((v->>'adjustments')::numeric),0)::text) INTO totals FROM (SELECT public.payment_balances(id) v FROM public.profiles) s; ELSE totals:=public.payment_balances(u); END IF;
RETURN jsonb_build_object('policy',to_jsonb(p),'next_payout',next_date,'balances',totals,'accepted',EXISTS(SELECT 1 FROM public.publisher_policy_acceptances WHERE user_id=u AND version=p.version),'batches',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.period_start DESC) FROM public.publisher_earnings_batches b WHERE all_publishers OR user_id=u),'[]'::jsonb),'payments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY requested_at DESC) FROM public.payments x WHERE all_publishers OR user_id=u),'[]'::jsonb),'adjustments',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC) FROM public.publisher_earnings_adjustments x WHERE all_publishers OR user_id=u),'[]'::jsonb),'appeals',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC) FROM public.publisher_adjustment_appeals x WHERE all_publishers OR user_id=u),'[]'::jsonb),'quality',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC) FROM public.publisher_quality_reports x WHERE all_publishers OR user_id=u),'[]'::jsonb),'events',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC) FROM public.publisher_payment_events x WHERE all_publishers OR user_id=u),'[]'::jsonb),'notifications',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC) FROM (SELECT id,title,body,read,created_at FROM public.notifications WHERE user_id=u AND kind='payment' ORDER BY created_at DESC LIMIT 30) x),'[]'::jsonb),'publishers',CASE WHEN all_publishers THEN (SELECT jsonb_agg(jsonb_build_object('id',id,'email',email,'publisher_id',publisher_id,'name',name)) FROM public.profiles) ELSE '[]'::jsonb END);
END $$;
REVOKE ALL ON FUNCTION public.payment_snapshot(uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.payment_snapshot(uuid,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.payment_operate(actor uuid, operation text, d jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE u uuid; p public.publisher_payment_policy; b public.publisher_earnings_batches; pay public.payments; adj public.publisher_earnings_adjustments; appeal public.publisher_adjustment_appeals; account public.publisher_payment_accounts; amount numeric(20,6); reason text; key text; target uuid; result jsonb; is_admin boolean; bal jsonb; outcome text;
BEGIN
is_admin:=public.has_role(actor,'admin'); reason:=nullif(trim(d->>'reason'),''); key:=nullif(d->>'key',''); p:=public.payment_policy_current();
IF operation NOT IN ('accept_policy','save_account','request_payout','appeal') AND NOT is_admin THEN RAISE EXCEPTION 'Admin permission required'; END IF;
IF operation NOT IN ('accept_policy','save_account') AND reason IS NULL THEN RAISE EXCEPTION 'A documented reason is required'; END IF;
IF operation='accept_policy' THEN IF (d->>'version')::integer<>p.version OR NOT coalesce((d->>'accepted')::boolean,false) THEN RAISE EXCEPTION 'Accept the current policy'; END IF; INSERT INTO public.publisher_policy_acceptances(user_id,version) VALUES(actor,p.version) ON CONFLICT DO NOTHING; RETURN jsonb_build_object('ok',true);
ELSIF operation='save_account' THEN IF nullif(trim(d->>'destination'),'') IS NULL THEN RAISE EXCEPTION 'Payment destination is required'; END IF; INSERT INTO public.publisher_payment_accounts(user_id,method,destination) VALUES(actor,(d->>'method')::public.payment_method,d->>'destination') ON CONFLICT(user_id) DO UPDATE SET method=excluded.method,destination=excluded.destination,verified=false,updated_at=now(); RETURN jsonb_build_object('ok',true);
ELSIF operation='configure_policy' THEN UPDATE public.publisher_payment_policy SET minimum=(d->>'minimum')::numeric,verification_days=(d->>'verification_days')::integer,weekday=(d->>'weekday')::integer,hour_utc=(d->>'hour_utc')::integer,version=version+1 WHERE id; u:=actor; target:=actor;
ELSIF operation='account_review' THEN u:=(d->>'user_id')::uuid; PERFORM pg_advisory_xact_lock(hashtext(u::text)); SELECT * INTO account FROM public.publisher_payment_accounts WHERE user_id=u FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Publisher must submit a payment account first'; END IF; UPDATE public.publisher_payment_accounts SET verified=coalesce((d->>'verified')::boolean,verified),on_hold=coalesce((d->>'on_hold')::boolean,on_hold),reason=reason,updated_at=now() WHERE user_id=u; target:=u;
ELSIF operation IN ('batch_approve','batch_hold','adjustment','quality_review') THEN
SELECT * INTO b FROM public.publisher_earnings_batches WHERE id=(d->>'batch_id')::uuid; IF NOT FOUND THEN RAISE EXCEPTION 'Batch not found'; END IF; u:=b.user_id; PERFORM pg_advisory_xact_lock(hashtext(u::text)); SELECT * INTO b FROM public.publisher_earnings_batches WHERE id=b.id FOR UPDATE; target:=b.id;
IF operation='batch_approve' THEN IF b.status='finalized' THEN RETURN jsonb_build_object('ok',true); END IF; IF b.reconciliation_open THEN RAISE EXCEPTION 'Source reconciliation must be resolved, not bypassed'; END IF; IF NOT EXISTS(SELECT 1 FROM public.publisher_quality_reports WHERE batch_id=b.id AND status IN ('Clean','Adjustment Applied')) THEN RAISE EXCEPTION 'Document traffic validation before approval'; END IF; UPDATE public.publisher_earnings_batches SET approved=true,investigation_open=false,status='under_verification' WHERE id=b.id;
ELSIF operation='batch_hold' THEN UPDATE public.publisher_earnings_batches SET approved=false,investigation_open=true,status='on_hold' WHERE id=b.id;
ELSIF operation='quality_review' THEN IF b.status='finalized' THEN RAISE EXCEPTION 'Finalized quality history cannot be edited'; END IF; IF nullif(trim(d->>'evidence'),'') IS NULL THEN RAISE EXCEPTION 'Validation evidence is required'; END IF; INSERT INTO public.publisher_quality_reports(user_id,batch_id,impressions,validated_impressions,invalid_impressions,status,evidence) VALUES(u,b.id,(d->>'impressions')::bigint,(d->>'validated_impressions')::bigint,(d->>'invalid_impressions')::bigint,d->>'status',d->>'evidence'); IF d->>'status' IN ('Under Review','Restricted') THEN UPDATE public.publisher_earnings_batches SET investigation_open=true,approved=false,status='on_hold' WHERE id=b.id; END IF;
ELSE IF b.status='finalized' THEN RAISE EXCEPTION 'Use a reconciliation reversal for finalized earnings'; END IF; amount:=(d->>'amount')::numeric; IF amount<=0 OR amount+b.adjustment>b.gross THEN RAISE EXCEPTION 'Adjustment exceeds attributable batch earnings'; END IF; IF nullif(trim(d->>'evidence'),'') IS NULL OR nullif(trim(d->>'evidence_key'),'') IS NULL THEN RAISE EXCEPTION 'Attribution evidence and unique evidence reference required'; END IF;
INSERT INTO public.publisher_earnings_adjustments(user_id,batch_id,amount,reason,evidence,evidence_key,created_by) VALUES(u,b.id,amount,reason,d->>'evidence',d->>'evidence_key',actor) RETURNING * INTO adj;
UPDATE public.publisher_earnings_batches SET adjustment=adjustment+amount,approved=false WHERE id=b.id;
INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,actor_id,idempotency_key) VALUES(u,b.id,'invalid_adjustment',-amount,reason,actor,'adjustment:'||adj.id);
PERFORM public.payment_notify(u,'Invalid traffic adjustment applied',amount::text||' USD excluded. Evidence: '||(d->>'evidence_key')||'. You may appeal this adjustment.'); END IF;
ELSIF operation='appeal' THEN SELECT * INTO adj FROM public.publisher_earnings_adjustments WHERE id=(d->>'adjustment_id')::uuid AND user_id=actor AND reversed_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Adjustment unavailable'; END IF; u:=actor; target:=adj.id; INSERT INTO public.publisher_adjustment_appeals(user_id,adjustment_id,reason) VALUES(actor,adj.id,reason); UPDATE public.publisher_earnings_batches SET investigation_open=true,approved=false,status='on_hold' WHERE id=adj.batch_id;
ELSIF operation='appeal_resolve' THEN SELECT * INTO appeal FROM public.publisher_adjustment_appeals WHERE id=(d->>'appeal_id')::uuid FOR UPDATE; IF NOT FOUND OR appeal.status<>'pending' THEN RAISE EXCEPTION 'Pending appeal required'; END IF; SELECT * INTO adj FROM public.publisher_earnings_adjustments WHERE id=appeal.adjustment_id FOR UPDATE; SELECT * INTO b FROM public.publisher_earnings_batches WHERE id=adj.batch_id FOR UPDATE; u:=appeal.user_id; target:=appeal.id; outcome:=d->>'outcome'; IF outcome NOT IN ('approved','rejected') THEN RAISE EXCEPTION 'Invalid resolution'; END IF;
IF outcome='approved' AND adj.reversed_at IS NULL THEN UPDATE public.publisher_earnings_adjustments SET reversed_at=now() WHERE id=adj.id; UPDATE public.publisher_earnings_batches SET adjustment=adjustment-adj.amount WHERE id=b.id; INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,actor_id,idempotency_key) VALUES(u,b.id,CASE WHEN b.finalized_at IS NOT NULL THEN 'adjustment_reversal' ELSE 'pending_adjustment_reversal' END,adj.amount,reason,actor,'reversal:'||adj.id); END IF;
UPDATE public.publisher_adjustment_appeals SET status=outcome,resolution=reason,resolved_at=now() WHERE id=appeal.id; PERFORM public.payment_notify(u,'Appeal status updated','Appeal '||outcome||': '||reason);
ELSIF operation IN ('request_payout','admin_request_payout') THEN
u:=CASE WHEN operation='request_payout' THEN actor ELSE (d->>'user_id')::uuid END; PERFORM pg_advisory_xact_lock(hashtext(u::text)); IF key IS NULL THEN RAISE EXCEPTION 'Idempotency key required'; END IF; SELECT * INTO pay FROM public.payments WHERE idempotency_key=key; IF FOUND THEN IF pay.user_id<>u THEN RAISE EXCEPTION 'Idempotency conflict'; END IF; RETURN jsonb_build_object('ok',true,'id',pay.id); END IF;
IF NOT EXISTS(SELECT 1 FROM public.publisher_policy_acceptances WHERE user_id=u AND version=p.version) THEN RAISE EXCEPTION 'Current payment policy acknowledgement required'; END IF; bal:=public.payment_balances(u); amount:=(d->>'amount')::numeric; IF NOT (bal->>'eligible')::boolean OR amount<p.minimum OR amount>(bal->>'available')::numeric OR amount<>round(amount,2) THEN RAISE EXCEPTION 'Payout requires verified available balance and minimum threshold'; END IF;
SELECT * INTO account FROM public.publisher_payment_accounts WHERE user_id=u; INSERT INTO public.payments(user_id,amount,method,destination,status,ledger_managed,lifecycle_status,idempotency_key,reference_id,earnings_period_start,earnings_period_end) VALUES(u,amount,account.method,account.destination,'pending',true,'payment_eligible',key,'AP-'||upper(substr(gen_random_uuid()::text,1,8)),(SELECT min(period_start) FROM public.publisher_earnings_batches WHERE user_id=u AND finalized_at IS NOT NULL),(SELECT max(period_end) FROM public.publisher_earnings_batches WHERE user_id=u AND finalized_at IS NOT NULL)) RETURNING * INTO pay;
target:=pay.id; INSERT INTO public.publisher_payment_events(user_id,payment_id,kind,amount,reason,actor_id,idempotency_key) VALUES(u,pay.id,'payment_scheduled',amount,reason,actor,'scheduled:'||pay.id); PERFORM public.payment_notify(u,'Payment scheduled','Payout request is eligible for the weekly release window.');
ELSIF operation IN ('payment_approve','payment_hold','payment_release','payment_paid','payment_failed','payment_reconcile','payment_reject') THEN
SELECT * INTO pay FROM public.payments WHERE id=(d->>'payment_id')::uuid; IF NOT FOUND THEN RAISE EXCEPTION 'Payment not found'; END IF; u:=pay.user_id; target:=pay.id; PERFORM pg_advisory_xact_lock(hashtext(u::text)); SELECT * INTO pay FROM public.payments WHERE id=pay.id FOR UPDATE; IF pay.status='paid' THEN RAISE EXCEPTION 'Paid payment history is immutable'; END IF;
IF operation='payment_hold' THEN outcome:='on_hold'; UPDATE public.payments SET lifecycle_status=outcome,hold_reason=reason WHERE id=pay.id;
ELSIF operation='payment_approve' THEN IF NOT pay.ledger_managed OR pay.status NOT IN ('pending','approved') OR pay.lifecycle_status='on_hold' THEN RAISE EXCEPTION 'Verified eligible payment required'; END IF; outcome:='payment_eligible'; UPDATE public.payments SET status='approved',lifecycle_status=outcome WHERE id=pay.id;
ELSIF operation='payment_release' THEN
IF NOT pay.ledger_managed OR pay.status<>'approved' THEN RAISE EXCEPTION 'Approved ledger payment required'; END IF; SELECT * INTO account FROM public.publisher_payment_accounts WHERE user_id=u;
IF NOT coalesce(account.verified,false) OR account.on_hold OR pay.lifecycle_status='on_hold' OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND status='active' AND kyc_status='verified') OR EXISTS(SELECT 1 FROM public.publisher_earnings_batches WHERE user_id=u AND (investigation_open OR reconciliation_open)) OR EXISTS(SELECT 1 FROM public.publisher_adjustment_appeals WHERE user_id=u AND status='pending') THEN RAISE EXCEPTION 'Account review, payment hold or reconciliation blocks release'; END IF;
IF extract(dow from now() AT TIME ZONE 'UTC')::integer<>p.weekday OR extract(hour from now() AT TIME ZONE 'UTC')<p.hour_utc THEN RAISE EXCEPTION 'Outside configured weekly payout window'; END IF; outcome:='processing'; UPDATE public.payments SET status='processing',lifecycle_status=outcome,hold_reason=NULL WHERE id=pay.id;
ELSIF operation='payment_paid' THEN IF pay.status<>'processing' OR nullif(trim(d->>'reference'),'') IS NULL OR NOT coalesce((d->>'confirmed')::boolean,false) THEN RAISE EXCEPTION 'Actual payment confirmation and transaction reference required'; END IF; IF pay.lifecycle_status='on_hold' THEN RAISE EXCEPTION 'Resolve hold before confirmation'; END IF; outcome:='paid'; UPDATE public.payments SET status='paid',lifecycle_status=outcome,confirmed_at=now(),paid_at=now(),tx_hash=d->>'reference' WHERE id=pay.id;
ELSIF operation='payment_failed' THEN IF pay.status<>'processing' THEN RAISE EXCEPTION 'Processing payment required'; END IF; outcome:='failed'; UPDATE public.payments SET status='failed',lifecycle_status=outcome,hold_reason=reason WHERE id=pay.id;
ELSIF operation='payment_reconcile' THEN IF pay.status<>'failed' OR pay.reconciled_at IS NOT NULL THEN RAISE EXCEPTION 'Unreconciled failed payment required'; END IF; outcome:='failed_reconciled'; UPDATE public.payments SET lifecycle_status=outcome,reconciled_at=now() WHERE id=pay.id;
ELSE IF pay.status='processing' THEN RAISE EXCEPTION 'Reconcile processing payments before rejection'; END IF; outcome:='rejected'; UPDATE public.payments SET status='rejected',lifecycle_status=outcome,hold_reason=reason WHERE id=pay.id; END IF;
INSERT INTO public.publisher_payment_events(user_id,payment_id,kind,amount,reason,actor_id,idempotency_key) VALUES(u,pay.id,outcome,CASE WHEN outcome IN ('failed_reconciled','rejected') THEN pay.amount ELSE 0 END,reason,actor,coalesce(key,gen_random_uuid()::text)); PERFORM public.payment_notify(u,'Payment '||replace(outcome,'_',' '),reason);
ELSE RAISE EXCEPTION 'Unsupported payment operation'; END IF;
IF is_admin THEN INSERT INTO public.audit_logs(admin_id,action,target_type,target_id,meta) VALUES(actor,'finance.'||operation,'payment_management',target::text,jsonb_build_object('reason',reason,'data',d,'publisher_id',u)); END IF;
RETURN jsonb_build_object('ok',true,'id',target);
END $$;
REVOKE ALL ON FUNCTION public.payment_operate(uuid,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.payment_operate(uuid,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.payment_record_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Payment records cannot be deleted'; END IF;
IF TG_OP='INSERT' AND NEW.status='paid' AND (NEW.confirmed_at IS NULL OR nullif(trim(NEW.tx_hash),'') IS NULL) THEN RAISE EXCEPTION 'Actual payment confirmation required'; END IF;
IF TG_OP='UPDATE' THEN IF OLD.status='paid' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'Paid records are immutable'; END IF; IF NEW.amount<>OLD.amount OR NEW.user_id<>OLD.user_id OR NEW.method<>OLD.method OR NEW.destination IS DISTINCT FROM OLD.destination THEN RAISE EXCEPTION 'Financial payment terms are immutable'; END IF; IF NEW.status='paid' AND (NEW.confirmed_at IS NULL OR nullif(trim(NEW.tx_hash),'') IS NULL) THEN RAISE EXCEPTION 'Actual payment confirmation required'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_payment_records BEFORE INSERT OR UPDATE OR DELETE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.payment_record_guard();